<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
 if($action==='delete_post'&&$id){db()->prepare('DELETE FROM blog_posts WHERE id=?')->execute([$id]);$notice='Story deleted.';}
 elseif($action==='delete_gallery'&&$id){db()->prepare('DELETE FROM gallery WHERE id=?')->execute([$id]);$notice='Gallery image deleted.';}
 elseif(in_array($action,['save_post','save_gallery'],true)){try{if($action==='save_post'){$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$excerpt=trim((string)($_POST['excerpt']??''));$status=(string)($_POST['status']??'draft');$category=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT)?:null;if($title===''||$body===''||!in_array($status,['draft','published'],true))throw new RuntimeException('Enter a title, body and valid publishing status.');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$title)),'-')).'-'.strtolower(bin2hex(random_bytes(3)));$image=save_uploaded_image('image','blog');if($id){if($image)$sql='UPDATE blog_posts SET title=?,excerpt=?,body=?,category_id=?,status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),NULL),image=? WHERE id=?';else$sql='UPDATE blog_posts SET title=?,excerpt=?,body=?,category_id=?,status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),NULL) WHERE id=?';$args=[$title,$excerpt?:null,$body,$category,$status,$status];if($image)$args[]=$image;$args[]=$id;db()->prepare($sql)->execute($args);}else db()->prepare('INSERT INTO blog_posts (category_id,author_id,title,slug,excerpt,body,image,status,published_at) VALUES (?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))')->execute([$category,current_user()['id'],$title,$slug,$excerpt?:null,$body,$image,$status,$status]);$notice='Story saved.';}else{$title=trim((string)($_POST['gallery_title']??''));$description=trim((string)($_POST['gallery_description']??''));$category=filter_var($_POST['gallery_category']??null,FILTER_VALIDATE_INT)?:null;$image=save_uploaded_image('gallery_image','gallery');if($id){if($title==='')throw new RuntimeException('Image title is required.');if($image)db()->prepare('UPDATE gallery SET title=?,description=?,category_id=?,image=? WHERE id=?')->execute([$title,$description?:null,$category,$image,$id]);else db()->prepare('UPDATE gallery SET title=?,description=?,category_id=? WHERE id=?')->execute([$title,$description?:null,$category,$id]);}else{if($title===''||!$image)throw new RuntimeException('Provide a title and image for a new gallery entry.');db()->prepare('INSERT INTO gallery (category_id,title,description,image) VALUES (?,?,?,?)')->execute([$category,$title,$description?:null,$image]);}$notice='Gallery entry saved.';}}catch(RuntimeException|PDOException $exception){$error=$exception instanceof RuntimeException?$exception->getMessage():'The content could not be saved.';error_log('Content save failed: '.$exception->getMessage());}}
}
$editId=filter_input(INPUT_GET,'edit_post',FILTER_VALIDATE_INT);$edit=null;if($editId){$q=db()->prepare('SELECT * FROM blog_posts WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;}
$posts=db()->query('SELECT id,title,status,published_at FROM blog_posts ORDER BY created_at DESC LIMIT 100')->fetchAll();$gallery=db()->query('SELECT g.*,gc.name AS category_name FROM gallery g LEFT JOIN gallery_categories gc ON gc.id=g.category_id ORDER BY g.created_at DESC LIMIT 100')->fetchAll();$blogCats=db()->query('SELECT id,name FROM blog_categories ORDER BY name')->fetchAll();$galleryCats=db()->query('SELECT id,name FROM gallery_categories ORDER BY name')->fetchAll();$adminTitle='Blog & gallery · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Blog & gallery</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?>
<div class="mt-7 grid gap-6 xl:grid-cols-2"><section class="bg-white p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit story':'Write a story' ?></h2><form method="post" enctype="multipart/form-data" class="mt-4 grid gap-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_post"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label class="text-sm">Title<input class="form-control mt-1" name="title" required value="<?= e($edit['title']??'') ?>"></label><label class="text-sm">Category<select class="form-control mt-1" name="category_id"><option value="">Uncategorised</option><?php foreach($blogCats as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm">Excerpt<input class="form-control mt-1" name="excerpt" value="<?= e($edit['excerpt']??'') ?>"></label><label class="text-sm">Article text<textarea class="form-control mt-1" name="body" rows="7" required><?= e($edit['body']??'') ?></textarea><span class="mt-1 block text-xs text-gray-500">Formatting: leave a blank line between paragraphs, start a line with “## ” for a heading and “- ” for a bullet point.</span></label><label class="text-sm">Featured image<input class="form-control mt-1" type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="text-sm">Publishing status<select class="form-control mt-1" name="status"><option value="draft" <?= ($edit['status']??'draft')==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= ($edit['status']??'')==='published'?'selected':'' ?>>Published</option></select></label><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Save story</button></form><div class="mt-6 divide-y"><?php foreach($posts as $post): ?><div class="flex items-center justify-between gap-3 py-3 text-sm"><span><?= e($post['title']) ?> <small class="text-gray-500">(<?= e($post['status']) ?>)</small></span><span class="flex gap-3"><a class="underline" href="?edit_post=<?= (int)$post['id'] ?>">Edit</a><form method="post" data-confirm="Delete this story?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_post"><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><button class="text-red-700 underline">Delete</button></form></span></div><?php endforeach; ?></div></section>
<section class="bg-white p-5"><h2 class="font-serif text-2xl">Gallery images</h2><form method="post" enctype="multipart/form-data" class="mt-4 grid gap-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_gallery"><label class="text-sm">Title<input class="form-control mt-1" name="gallery_title" required></label><label class="text-sm">Category<select class="form-control mt-1" name="gallery_category"><option value="">Uncategorised</option><?php foreach($galleryCats as $cat): ?><option value="<?= (int)$cat['id'] ?>"><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm">Description<textarea class="form-control mt-1" name="gallery_description" rows="2"></textarea></label><label class="text-sm">Image<input class="form-control mt-1" type="file" name="gallery_image" required accept="image/jpeg,image/png,image/webp"></label><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Add image</button></form><div class="mt-6 grid grid-cols-2 gap-3"><?php foreach($gallery as $entry): ?><article class="border border-black/5 p-3"><img class="aspect-square w-full object-cover" src="<?= e(url('uploads/gallery/'.rawurlencode(basename($entry['image'])))) ?>" alt="<?= e($entry['title']) ?>"><p class="mt-2 text-sm font-semibold"><?= e($entry['title']) ?></p><form method="post" class="mt-2 flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_gallery"><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><input class="form-control min-w-0" name="gallery_title" value="<?= e($entry['title']) ?>" required><button class="text-xs underline">Save</button></form><form method="post" class="mt-2" data-confirm="Delete this gallery image?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_gallery"><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><button class="text-xs text-red-700 underline">Delete</button></form></article><?php endforeach; ?></div></section></div>
